{
  "spec": "This plan adds CSV and Markdown output formats to the exporter tool, ensuring they integrate with the existing registry and CLI. It introduces a `--fields` argument to allow column selection and ordering across all formats, including the new ones. Missing keys in records are handled by writing empty cells in CSV and Markdown outputs. The CLI is updated to support `--list-formats` and default to stdout when no destination is provided. Existing JSON and text modules remain unchanged to preserve byte-for-byte compatibility.",
  "stack": "Python, pytest, csv, markdown",
  "tasks": [
    {
      "id": 1,
      "title": "Add csv and markdown to allowed extensions in settings",
      "files": [
        "exporter/settings.py"
      ],
      "test": "tests/test_settings.py: Check that EXTENSIONS contains 'csv' and 'markdown'.",
      "check": "python -m pytest tests/test_settings.py -v",
      "expect": "PASSED"
    },
    {
      "id": 2,
      "title": "Implement CSV writing logic with header and quoting",
      "files": [
        "exporter/formats/csv_fmt.py"
      ],
      "test": "tests/test_csv.py: Check that output includes a header row and uses standard csv quoting, handling missing keys as empty cells.",
      "check": "python -m pytest tests/test_csv.py -v",
      "expect": "PASSED"
    },
    {
      "id": 3,
      "title": "Implement Markdown table writing with pipe escaping",
      "files": [
        "exporter/formats/markdown_fmt.py"
      ],
      "test": "tests/test_markdown.py: Check that output is a valid Markdown table and '|' in values is escaped as '\\|', handling missing keys as empty cells.",
      "check": "python -m pytest tests/test_markdown.py -v",
      "expect": "PASSED"
    },
    {
      "id": 4,
      "title": "Register csv and markdown formats in the registry",
      "files": [
        "exporter/formats/__init__.py"
      ],
      "test": "tests/test_registry.py: Check that formats.names() includes 'csv' and 'markdown'.",
      "check": "python -m pytest tests/test_registry.py -v",
      "expect": "PASSED"
    },
    {
      "id": 5,
      "title": "Add --fields argument to CLI for column selection",
      "files": [
        "exporter/cli.py"
      ],
      "test": "tests/test_cli.py: Check that --fields filters columns and respects order, working with csv and markdown formats.",
      "check": "python -m pytest tests/test_cli.py::test_fields_filter -v",
      "expect": "PASSED"
    },
    {
      "id": 6,
      "title": "Update CLI to default to stdout when no destination is given",
      "files": [
        "exporter/cli.py"
      ],
      "test": "tests/test_cli.py: Check that output goes to stdout when no dst is provided.",
      "check": "python -m pytest tests/test_cli.py::test_stdout_default -v",
      "expect": "PASSED"
    },
    {
      "id": 7,
      "title": "Add --list-formats option to CLI",
      "files": [
        "exporter/cli.py"
      ],
      "test": "tests/test_cli.py: Check that --list-formats prints all registered formats including csv and markdown.",
      "check": "python -m pytest tests/test_cli.py::test_list_formats -v",
      "expect": "PASSED"
    },
    {
      "id": 8,
      "title": "Verify JSON output remains unchanged",
      "files": [
        "exporter/formats/json_fmt.py"
      ],
      "test": "tests/test_json.py: Check that JSON output is identical to previous versions.",
      "check": "python -m pytest tests/test_json.py -v",
      "expect": "PASSED"
    }
  ]
}

